INSERT INTO setting (id, type, value, note) VALUES ('wings.no-fly.tag', 'text', 'sb_no_fly', '');
INSERT INTO setting (id, type, value, note) VALUES ('wings.no-fly.boss-radius', 'int', '40', 'A boss (vanilla Boss entity or a mob with the scoreboard tag combat.boss-tag) within this many blocks counts as a no-fly zone, so the arenas are safe even when the boss feature does not flag its players. 0 disables.');
INSERT INTO setting (id, type, value, note) VALUES ('wings.max-level', 'int', '10', '');
