INSERT INTO setting (id, type, value, note) VALUES ('wings.energy.drain-hover', 'real', '2.0', '');
INSERT INTO setting (id, type, value, note) VALUES ('wings.energy.drain-glide', 'real', '1.0', 'Gliding (the Wings are also an elytra): energy per second, and per firework rocket boost. Gliding and rockets are refused without energy and wherever flying is refused.');
INSERT INTO setting (id, type, value, note) VALUES ('wings.energy.firework-cost', 'real', '12.0', '');
INSERT INTO setting (id, type, value, note) VALUES ('wings.energy.dive-regen', 'real', '3.0', 'Diving (steep descent while gliding) gives energy back, per second, from abilities.dive-recovery.level.');
INSERT INTO setting (id, type, value, note) VALUES ('wings.energy.island-drain-factor', 'real', '0.5', 'Drain factor while flying over an island (any island).');
INSERT INTO setting (id, type, value, note) VALUES ('wings.energy.regen-ground', 'real', '10.0', 'Regeneration per second on the ground, and the multiplier on an island (inside its border).');
INSERT INTO setting (id, type, value, note) VALUES ('wings.energy.regen-island-multiplier', 'real', '2.0', '');
INSERT INTO setting (id, type, value, note) VALUES ('wings.energy.regen-delay-ticks', 'int', '20', 'Ticks without flying before regeneration starts.');
INSERT INTO setting (id, type, value, note) VALUES ('wings.energy.resume-fraction', 'real', '0.15', 'After running dry you cannot take off again before this fraction of the capacity is back.');
INSERT INTO setting (id, type, value, note) VALUES ('wings.energy.low-fraction', 'real', '0.2', 'The bar turns red and a warning sound plays under this fraction.');
INSERT INTO setting (id, type, value, note) VALUES ('wings.energy.bar-hide-seconds', 'int', '4', 'The energy bar disappears this many seconds after being full while on the ground.');
INSERT INTO setting (id, type, value, note) VALUES ('wings.combat.seconds', 'int', '8', 'Flight is disabled for this long after taking damage from the sources below.');
