INSERT INTO setting (id, type, value, note) VALUES ('wings.combat.from-mobs', 'bool', 'false', '');
INSERT INTO setting (id, type, value, note) VALUES ('wings.combat.tag-attackers', 'bool', 'true', 'Also tag the attacker when a player hits another player. Tagging the attacker too stops hit-and-fly-away in the air; the COMBAT emergency reason below keeps it safe.');
INSERT INTO setting (id, type, value, note) VALUES ('wings.combat.boss-tag', 'text', 'sb_boss', 'A mob counts as a boss when it has this scoreboard tag, is a vanilla Boss, or has at least this much max health.');
