INSERT INTO setting (id, type, value, note) VALUES ('wings.emergency.reasons', 'list', '', 'Slow falling (no fall damage) when flight ends in mid air for one of these reasons: ENERGY, UNEQUIP, WORLD, COMBAT, ZONE.');
