INSERT INTO setting (id, type, value, note) VALUES ('wings.emergency.void-rescue', 'bool', 'true', 'While a slow fall is active (and a few seconds after), void damage is cancelled and the player is teleported back to the last solid ground they stood on (else their island home, else the world spawn). Nobody dies of an empty bar.');
